// The WebAssembly module itself: the kernel runs, bodies cross as numbers, failures throw.
import { test } from 'node:test'
import assert from 'node:assert/strict'
// @ts-ignore: generated by Emscripten (npm run wasm)
import createSmlib from '../wasm/smlibjs.mjs'

const K = await createSmlib()
K.init()

test('a box has 6 faces, 12 edges and 8 vertices', () => {
  const box = K.create_box([0, 0, 0], 60, 44, 28)
  assert.deepEqual(K.brep_counts(box), [6, 12, 8])
  K.delete_brep(box)
})

test('a cylinder cut from a block leaves its wall as new faces', () => {
  const block = K.create_box([0, 0, 0], 60, 44, 28)
  const cylinder = K.create_cylinder([56.2, 3.8, 0], 19, 44)
  const result = K.boolean(block, cylinder, K.BO_DIFFERENCE)
  const [faces] = K.brep_counts(result)
  assert.ok(faces > 6, `${faces} faces`)
  K.delete_brep(result)
})

test('a failing kernel call throws an Error naming the call', () => {
  assert.throws(() => K.boolean(0, 0, K.BO_UNION), /Brep/)
})
